<template><q-page class="customer-flow-page"><div class="page-heading"><div><div class="eyebrow">REPORTING</div><h1 class="page-title">Account statements</h1><p class="page-subtitle">A dated ledger of account movements, with opening and closing balances.</p></div></div><section class="customer-panel"><q-form class="row q-col-gutter-md items-start" @submit="generate"><q-select class="col-12 col-md-4" v-model="accountId" filled label="Account" emit-value map-options :options="accounts" :rules="[v => !!v || 'Choose an account']" /><DatePickerField class="col-6 col-md-3" v-model="start" filled label="From date" :rules="[v => !!v || 'Required']" /><DatePickerField class="col-6 col-md-3" v-model="end" filled label="Through date" :rules="[v => !!v || 'Required']" /><div class="col-12 col-md-2"><q-btn color="primary" type="submit" label="Generate" :loading="busy" :disable="!accounts.length" /></div></q-form><q-banner v-if="error" class="bank-feedback q-mt-md">{{ error }}</q-banner></section><section v-if="report" class="customer-panel q-mt-lg"><div class="row justify-between items-center q-gutter-sm"><div><h2 class="section-heading">{{ report.customer }}</h2><p>{{ report.account_number }} · {{ report.account_type }}</p><p class="page-subtitle">{{ report.start }} through {{ report.end }} · {{ report.currency }} · Simulated banking</p></div><div class="row q-gutter-sm"><q-btn outline label="Export CSV" icon="download" @click="csv" /><q-btn outline label="Print / Save PDF" icon="print" @click="printReport" /></div></div><div class="row q-col-gutter-lg q-my-md"><div v-for="(label,key) in totals" :key="key" class="col-6 col-md-3"><div class="page-subtitle">{{ label }}</div><strong>{{ money(report[key]) }}</strong></div></div><q-table flat :rows="report.rows" :columns="columns" :pagination="{rowsPerPage:15}" /><p class="page-subtitle q-mt-md">Ledger balances include recorded deposits, withdrawals, transfers, bills, fees, and interest. Investment reservations affect available funds only. Opening balance includes any initial balance carried forward.</p></section></q-page></template>
<script setup>
import DatePickerField from '@/components/DatePickerField.vue'
import { ref, onMounted } from 'vue'
import api from '@/services/api'
import { useAuthStore } from '@/stores/auth-store'
const auth = useAuthStore(), accounts = ref([]), accountId = ref(null), report = ref(null), busy = ref(false), error = ref('')
const today = new Date(), localDate = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
const start = ref(localDate(new Date(today.getFullYear(),today.getMonth(),1))), end = ref(localDate(today))
const money = v => Number(v).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})
const totals = {opening_balance:'Opening balance',total_credits:'Total credits',total_debits:'Total debits',closing_balance:'Closing balance'}
const columns = [{name:'date',field:'date',label:'Date',align:'left'}, {name:'description',field:'description',label:'Description',align:'left'}, {name:'reference',field:'reference',label:'Reference',align:'left'}, ...['debit','credit','balance'].map(k=>({name:k,field:k,label:k[0].toUpperCase()+k.slice(1),format:money}))]
onMounted(async()=>{try {accounts.value=(await api.get(auth.isCustomer?'/customer/accounts/':'/accounts/')).data.map(a=>({label:a.account_number,value:a.id})); if(accounts.value.length) accountId.value=accounts.value[0].value} catch {error.value='Could not load accounts. Refresh to try again.'}})
async function generate(){if(busy.value)return;busy.value=true;error.value='';report.value=null;try{report.value=(await api.get(`/reports/accounts/${accountId.value}/statement`,{params:{start:start.value,end:end.value}})).data}catch(e){error.value=e.response?.data?.detail||'Could not generate statement.'}finally{busy.value=false}}
const values = r => [r.date,r.description,r.reference,r.debit,r.credit,r.balance]
function csv(){const r=report.value;const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const lines=[['Bembank statement',r.account_number,r.customer],['Period',r.start,r.end],['Currency',r.currency],...Object.entries(totals).map(([k,v])=>[v,r[k]]),['Date','Description','Reference','Debit','Credit','Balance'],...r.rows.map(values)];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`bembank-statement-${r.start}-${r.end}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printReport(){const popup=window.open('','_blank');if(!popup){error.value='Allow the print window to open, then try again.';return}popup.opener=null;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const r=report.value;popup.document.write(`<!doctype html><html><head><title>Bembank account statement</title><style>body{font:12px Arial;margin:32px;color:#111}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ccc;text-align:left;overflow-wrap:anywhere}thead{display:table-header-group}tr{break-inside:avoid}h1{color:#17467b}</style></head><body><h1>Bembank · Account statement</h1><p>${esc(r.customer)} · ${esc(r.account_number)} · ${esc(r.account_type)}</p><p>${esc(r.start)} through ${esc(r.end)} · ${esc(r.currency)} · Simulated banking</p>${Object.entries(totals).map(([k,v])=>`<p>${v}: ${esc(money(r[k]))}</p>`).join('')}<table><thead><tr>${['Date','Description','Reference','Debit','Credit','Balance'].map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr>${values(row).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table><p>Ledger statement. Investment reservations affect available funds only.</p></body></html>`);popup.document.close();popup.focus();popup.print()}
</script>
